UPDATE users
SET failed_login_attempts = failed_login_attempts + 1
WHERE id = #{id}

UPDATE users
SET account_locked_until = #{lockUntil}
WHERE id = #{id}

UPDATE users
SET failed_login_attempts = 0, account_locked_until = NULL
WHERE id = #{id}

